    public void discountCost(){
        this.findWitchPoles();
        int size = Mth.clamp(this.witchPoles.size(), 0, 3);
        if (size > 0) {
            for (int i = 0; i < size; ++i) {
                this.totalCost *= 0.99F;
            }
        }
        if (this.level != null){
            if (this.level.getBiome(this.worldPosition).is(BiomeTags.HAS_SWAMP_HUT)){
                this.totalCost *= 0.99F;
            }
        }
    }

