    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    public static final class Client {

        public static void tick(Level world, BlockPos pos, BlockState state, VoidVaultClientData clientData, VoidVaultSharedData sharedData) {
            clientData.rotateDisplay();
            if (world.getGameTime() % 20L == 0L) {
                spawnConnectedParticles(world, pos, state, sharedData);
            }

            spawnAmbientParticles(world, pos, sharedData);
            playAmbientSound(world, pos, sharedData);
        }

        public static void spawnActivateParticles(Level world, BlockPos pos, BlockState state, VoidVaultSharedData sharedData) {
            spawnConnectedParticles(world, pos, state, sharedData);
            RandomSource random = world.random;

            for (int i = 0; i < 20; i++) {
                Vec3 vec3d = getRegularParticlesPos(pos, random);
                if (world instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3d.x(), vec3d.y(), vec3d.z(), 1, 0.0, 0.0, 0.0, 0.0F);
                    serverLevel.sendParticles(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), 1, 0.0, 0.0, 0.0, 0.0F);
                } else {
                    world.addParticle(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3d.x(), vec3d.y(), vec3d.z(), 0.0, 0.0, 0.0);
                    world.addParticle(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), 0.0, 0.0, 0.0);
                }
            }
        }

        public static void spawnDeactivateParticles(Level world, BlockPos pos) {
            RandomSource random = world.random;
            for (int i = 0; i < 20; i++) {
                Vec3 vec3d = getDeactivateParticlesPos(pos, random);
                Vec3 vec3d2 = new Vec3(random.nextGaussian() * 0.02, random.nextGaussian() * 0.02, random.nextGaussian() * 0.02);
                if (world instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), 0, vec3d2.x(), vec3d2.y(), vec3d2.z(), 0.5F);
                } else {
                    world.addParticle(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), vec3d2.x(), vec3d2.y(), vec3d2.z());
                }
            }
        }

        private static void spawnAmbientParticles(Level world, BlockPos pos, VoidVaultSharedData sharedData) {
            RandomSource random = world.getRandom();
            if (random.nextFloat() <= 0.5F) {
                Vec3 vec3d = getRegularParticlesPos(pos, random);
                if (world instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3d.x(), vec3d.y(), vec3d.z(), 1, 0.0, 0.0, 0.0, 0.0F);
                    if (hasDisplayItem(sharedData)) {
                        serverLevel.sendParticles(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), 1, 0.0, 0.0, 0.0, 0.0F);
                    }
                } else {
                    world.addParticle(new MagicAshSmokeParticleOption(0x3a0637, 0x691575), vec3d.x(), vec3d.y(), vec3d.z(), 0.0, 0.0, 0.0);
                    if (hasDisplayItem(sharedData)) {
                        world.addParticle(ModParticleTypes.SMALL_END_FIRE.get(), vec3d.x(), vec3d.y(), vec3d.z(), 0.0, 0.0, 0.0);
                    }
                }
            }
        }

        private static void spawnConnectedParticlesFor(Level world, Vec3 pos, Player player) {
            RandomSource random = world.random;
            Vec3 vec3d = pos.vectorTo(player.position().add(0.0, player.getBbHeight() / 2.0F, 0.0));
            int i = Mth.nextInt(random, 2, 5);

            for (int j = 0; j < i; j++) {
                Vec3 vec3d2 = vec3d.offsetRandom(random, 1.0F);
                world.addParticle(ModParticleTypes.VOID_VAULT_CONNECT.get(), pos.x(), pos.y(), pos.z(), vec3d2.x(), vec3d2.y(), vec3d2.z());
            }
        }

        private static void spawnConnectedParticles(Level world, BlockPos pos, BlockState state, VoidVaultSharedData sharedData) {
            Set<UUID> set = sharedData.getConnectedPlayers();
            if (!set.isEmpty()) {
                Vec3 vec3d = getConnectedParticlesOrigin(pos, state.getValue(VoidVaultBlock.FACING));

                for (UUID uUID : set) {
                    Player playerEntity = world.getPlayerByUUID(uUID);
                    if (playerEntity != null && isPlayerWithinConnectedParticlesRange(pos, sharedData, playerEntity)) {
                        spawnConnectedParticlesFor(world, vec3d, playerEntity);
                    }
                }
            }
        }

        private static boolean isPlayerWithinConnectedParticlesRange(BlockPos pos, VoidVaultSharedData sharedData, Player player) {
            return player.blockPosition().distSqr(pos) <= Mth.square(sharedData.getConnectedParticlesRange());
        }

        private static void playAmbientSound(Level world, BlockPos pos, VoidVaultSharedData sharedData) {
            if (hasDisplayItem(sharedData)) {
                RandomSource random = world.getRandom();
                if (random.nextFloat() <= 0.02F) {
                    world.playLocalSound(pos, ModSounds.VOID_VAULT_AMBIENT.get(), SoundSource.BLOCKS, (random.nextFloat() * 0.25F) + 0.75F, random.nextFloat() + 0.5F, false);
                }
            }
        }

        public static boolean hasDisplayItem(VoidVaultSharedData sharedData) {
            return sharedData.hasDisplayItem();
        }

        private static Vec3 getDeactivateParticlesPos(BlockPos pos, RandomSource random) {
            return Vec3.atLowerCornerOf(pos).add(Mth.nextDouble(random, 0.4, 0.6), Mth.nextDouble(random, 0.4, 0.6), Mth.nextDouble(random, 0.4, 0.6));
        }

        private static Vec3 getRegularParticlesPos(BlockPos pos, RandomSource random) {
            return Vec3.atLowerCornerOf(pos).add(Mth.nextDouble(random, 0.1, 0.9), Mth.nextDouble(random, 0.25, 0.75), Mth.nextDouble(random, 0.1, 0.9));
        }

        private static Vec3 getConnectedParticlesOrigin(BlockPos pos, Direction direction) {
            return Vec3.atBottomCenterOf(pos).add(direction.getStepX() * 0.5, 1.75, direction.getStepZ() * 0.5);
        }
    }

    public static final class Server {

        public static void tick(ServerLevel world, BlockPos pos, BlockState state, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
            VoidVaultState vaultState = state.getValue(VoidVaultBlock.STATE);
            if (shouldUpdateDisplayItem(world.getGameTime(), vaultState)) {
                updateDisplayItem(world, vaultState, config, sharedData, pos);
            }

            BlockState blockState = state;
            if (world.getGameTime() >= serverData.getStateUpdatingResumeTime()) {
                blockState = state.setValue(VoidVaultBlock.STATE, vaultState.update(world, pos, config, serverData, sharedData));
                if (!state.equals(blockState)) {
                    changeVaultState(world, pos, state, blockState, config, sharedData);
                }
            }

            if (serverData.dirty || sharedData.dirty) {
                VoidVaultBlockEntity.setChanged(world, pos, state);
                if (sharedData.dirty) {
                    world.sendBlockUpdated(pos, state, blockState, 2);
                }

                serverData.dirty = false;
                sharedData.dirty = false;
            }
        }

        public static void tryUnlock(
                ServerLevel world,
                BlockPos pos,
                BlockState state,
                VoidVaultConfig config,
                VoidVaultServerData serverData,
                VoidVaultSharedData sharedData,
                Player player,
                ItemStack stack
        ) {
            VoidVaultState vaultState = state.getValue(VoidVaultBlock.STATE);
            if (canBeUnlocked(config, vaultState)) {
                if (!isValidKey(config, stack)) {
                    playFailedUnlockSound(world, serverData, pos, ModSounds.VOID_VAULT_INSERT_FAIL.get());
                } else if (serverData.hasRewardedPlayer(player)) {
                    playFailedUnlockSound(world, serverData, pos, ModSounds.VOID_VAULT_REJECT.get());
                } else {
                    List<ItemStack> list = generateLoot(world, config, pos, player);
                    if (!list.isEmpty()) {
                        player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
                        if (!player.isCreative()) {
                            stack.shrink(config.keyItem().getCount());
                        }

                        unlock(world, state, pos, config, serverData, sharedData, list);
                        serverData.markPlayerAsRewarded(player);
                        sharedData.updateConnectedPlayers(world, pos, serverData, config, config.deactivationRange());
                    }
                }
            }
        }

        static void changeVaultState(ServerLevel world, BlockPos pos, BlockState oldState, BlockState newState, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            VoidVaultState vaultState = oldState.getValue(VoidVaultBlock.STATE);
            VoidVaultState vaultState2 = newState.getValue(VoidVaultBlock.STATE);
            world.setBlock(pos, newState, Block.UPDATE_ALL);
            vaultState.onStateChange(world, pos, vaultState2, config, sharedData);
        }

        public static void updateDisplayItem(ServerLevel world, VoidVaultState state, VoidVaultConfig config, VoidVaultSharedData sharedData, BlockPos pos) {
            if (!canBeUnlocked(config, state)) {
                sharedData.setDisplayItem(ItemStack.EMPTY);
            } else {
                ItemStack itemStack = generateDisplayItem(world, pos, config.overrideLootTableToDisplay().orElse(config.lootTable()));
                sharedData.setDisplayItem(itemStack);
            }
        }

        private static ItemStack generateDisplayItem(ServerLevel world, BlockPos pos, ResourceLocation lootTable) {
            LootTable lootTable2 = world.getServer().getLootData().getLootTable(lootTable);
            LootParams.Builder lootContextParameterSet = new LootParams.Builder(world).withParameter(LootContextParams.ORIGIN, Vec3.atCenterOf(pos));
            LootParams lootParams = lootContextParameterSet.create(LootContextParamSets.CHEST);
            List<ItemStack> list = lootTable2.getRandomItems(lootParams);
            return list.isEmpty() ? ItemStack.EMPTY : Util.getRandom(list, world.getRandom());
        }

        private static void unlock(ServerLevel world, BlockState state, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData, List<ItemStack> itemsToEject) {
            serverData.setItemsToEject(itemsToEject);
            sharedData.setDisplayItem(serverData.getItemToDisplay());
            serverData.setStateUpdatingResumeTime(world.getGameTime() + 14L);
            changeVaultState(world, pos, state, state.setValue(ModStateProperties.VOID_VAULT_STATE, VoidVaultState.UNLOCKING), config, sharedData);
        }

        private static List<ItemStack> generateLoot(ServerLevel world, VoidVaultConfig config, BlockPos pos, Player player) {
            LootTable lootTable = world.getServer().getLootData().getLootTable(config.lootTable());
            LootParams.Builder lootContextParameterSet = new LootParams.Builder(world)
                    .withParameter(LootContextParams.ORIGIN, Vec3.atCenterOf(pos))
                    .withLuck(player.getLuck())
                    .withParameter(LootContextParams.THIS_ENTITY, player);
            LootParams lootParams = lootContextParameterSet.create(LootContextParamSets.CHEST);
            return lootTable.getRandomItems(lootParams);
        }

        private static boolean canBeUnlocked(VoidVaultConfig config, VoidVaultState state) {
            return config.lootTable() != LootTable.EMPTY.getLootTableId() && !config.keyItem().isEmpty() && state != VoidVaultState.INACTIVE;
        }

        private static boolean isValidKey(VoidVaultConfig config, ItemStack stack) {
            return ItemStack.isSameItemSameTags(stack, config.keyItem()) && stack.getCount() >= config.keyItem().getCount();
        }

        private static boolean shouldUpdateDisplayItem(long time, VoidVaultState state) {
            return time % 20L == 0L && state == VoidVaultState.ACTIVE;
        }

        private static void playFailedUnlockSound(ServerLevel world, VoidVaultServerData serverData, BlockPos pos, SoundEvent soundEvent) {
            if (world.getGameTime() >= serverData.getLastFailedUnlockTime() + 15L) {
                world.playSound(null, pos, soundEvent, SoundSource.BLOCKS);
                serverData.setLastFailedUnlockTime(world.getGameTime());
            }
        }
    }
}

package com.Polarice3.Goety.common.blocks.entities.void_vault;

import com.Polarice3.Goety.utils.MathHelper;
import com.Polarice3.Goety.utils.ModUUIDUtil;
import com.google.common.annotations.VisibleForTesting;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import it.unimi.dsi.fastutil.objects.ObjectArrayList;
import it.unimi.dsi.fastutil.objects.ObjectLinkedOpenHashSet;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.*;

public class VoidVaultServerData {
    static final String SERVER_DATA_KEY = "server_data";
    public static Codec<VoidVaultServerData> CODEC = RecordCodecBuilder.create(
            instance -> instance.group(
                            ModUUIDUtil.CODEC_LINKED_SET.optionalFieldOf("rewarded_players", Set.of()).forGetter(data -> data.rewardedPlayers),
                            Codec.LONG.optionalFieldOf("state_updating_resumes_at", 0L).forGetter(data -> data.stateUpdatingResumesAt),
                            ItemStack.CODEC.listOf().optionalFieldOf("items_to_eject", List.of()).forGetter(data -> data.itemsToEject),
                            Codec.INT.optionalFieldOf("total_ejections_needed", 0).forGetter(data -> data.totalEjectionsNeeded)
                    )
                    .apply(instance, VoidVaultServerData::new)
    );
    private static final int MAX_STORED_REWARDED_PLAYERS = 128;
    private final Set<UUID> rewardedPlayers = new ObjectLinkedOpenHashSet<>();
    private long stateUpdatingResumesAt;
    private final List<ItemStack> itemsToEject = new ObjectArrayList<>();
    private long lastFailedUnlockTime;
    private int totalEjectionsNeeded;
    public boolean dirty;

    public VoidVaultServerData(Set<UUID> rewardedPlayers, long stateUpdatingResumesAt, List<ItemStack> itemsToEject, int totalEjectionsNeeded) {
        this.rewardedPlayers.addAll(rewardedPlayers);
        this.stateUpdatingResumesAt = stateUpdatingResumesAt;
        this.itemsToEject.addAll(itemsToEject);
        this.totalEjectionsNeeded = totalEjectionsNeeded;
    }

    public VoidVaultServerData() {
    }

    public void setLastFailedUnlockTime(long lastFailedUnlockTime) {
        this.lastFailedUnlockTime = lastFailedUnlockTime;
    }

    public long getLastFailedUnlockTime() {
        return this.lastFailedUnlockTime;
    }

    public Set<UUID> getRewardedPlayers() {
        return this.rewardedPlayers;
    }

    public boolean hasRewardedPlayer(Player player) {
        return this.rewardedPlayers.contains(player.getUUID());
    }

    @VisibleForTesting
    public void markPlayerAsRewarded(Player player) {
        this.rewardedPlayers.add(player.getUUID());
        if (this.rewardedPlayers.size() > 128) {
            Iterator<UUID> iterator = this.rewardedPlayers.iterator();
            if (iterator.hasNext()) {
                iterator.next();
                iterator.remove();
            }
        }

        this.markDirty();
    }

    public long getStateUpdatingResumeTime() {
        return this.stateUpdatingResumesAt;
    }

    public void setStateUpdatingResumeTime(long stateUpdatingResumesAt) {
        this.stateUpdatingResumesAt = stateUpdatingResumesAt;
        this.markDirty();
    }

    public List<ItemStack> getItemsToEject() {
        return this.itemsToEject;
    }

    public void finishEjecting() {
        this.totalEjectionsNeeded = 0;
        this.markDirty();
    }

    public void setItemsToEject(List<ItemStack> itemsToEject) {
        this.itemsToEject.clear();
        this.itemsToEject.addAll(itemsToEject);
        this.totalEjectionsNeeded = this.itemsToEject.size();
        this.markDirty();
    }

    public ItemStack getItemToDisplay() {
        return this.itemsToEject.isEmpty()
                ? ItemStack.EMPTY
                : Objects.requireNonNullElse(this.itemsToEject.get(this.itemsToEject.size() - 1), ItemStack.EMPTY);
    }

    public ItemStack getItemToEject() {
        if (this.itemsToEject.isEmpty()) {
            return ItemStack.EMPTY;
        } else {
            this.markDirty();
            return Objects.requireNonNullElse(this.itemsToEject.remove(this.itemsToEject.size() - 1), ItemStack.EMPTY);
        }
    }

    public void copyFrom(VoidVaultServerData data) {
        this.stateUpdatingResumesAt = data.getStateUpdatingResumeTime();
        this.itemsToEject.clear();
        this.itemsToEject.addAll(data.itemsToEject);
        this.rewardedPlayers.clear();
        this.rewardedPlayers.addAll(data.rewardedPlayers);
    }

    private void markDirty() {
        this.dirty = true;
    }

    public float getEjectSoundPitchModifier() {
        return this.totalEjectionsNeeded == 1 ? 1.0F : 1.0F - MathHelper.getLerpProgress((float)this.getItemsToEject().size(), 1.0F, (float)this.totalEjectionsNeeded);
    }
}

package com.Polarice3.Goety.common.blocks.entities.void_vault;

import com.Polarice3.Goety.utils.ModUUIDUtil;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import it.unimi.dsi.fastutil.objects.ObjectLinkedOpenHashSet;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.ItemStack;

import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

public class VoidVaultSharedData {
    static final String SHARED_DATA_KEY = "shared_data";
    public static Codec<VoidVaultSharedData> CODEC = RecordCodecBuilder.create(
            instance -> instance.group(
                            VoidVaultConfig.createOptionalCodec("display_item").forGetter(data -> data.displayItem),
                            ModUUIDUtil.CODEC_LINKED_SET.optionalFieldOf("connected_players", Set.of()).forGetter(data -> data.connectedPlayers),
                            Codec.DOUBLE.optionalFieldOf("connected_particles_range", VoidVaultConfig.DEFAULT.deactivationRange()).forGetter(data -> data.connectedParticlesRange)
                    )
                    .apply(instance, VoidVaultSharedData::new)
    );
    private ItemStack displayItem = ItemStack.EMPTY;
    private Set<UUID> connectedPlayers = new ObjectLinkedOpenHashSet<>();
    private double connectedParticlesRange = VoidVaultConfig.DEFAULT.deactivationRange();
    public boolean dirty;

    VoidVaultSharedData(ItemStack displayItem, Set<UUID> connectedPlayers, double connectedParticlesRange) {
        this.displayItem = displayItem;
        this.connectedPlayers.addAll(connectedPlayers);
        this.connectedParticlesRange = connectedParticlesRange;
    }

    public VoidVaultSharedData() {
    }

    public ItemStack getDisplayItem() {
        return this.displayItem;
    }

    public boolean hasDisplayItem() {
        return !this.displayItem.isEmpty();
    }

    public void setDisplayItem(ItemStack stack) {
        if (!ItemStack.isSameItem(this.displayItem, stack)) {
            this.displayItem = stack.copy();
            this.markDirty();
        }
    }

    public boolean hasConnectedPlayers() {
        return !this.connectedPlayers.isEmpty();
    }

    public Set<UUID> getConnectedPlayers() {
        return this.connectedPlayers;
    }

    public double getConnectedParticlesRange() {
        return this.connectedParticlesRange;
    }

    public void updateConnectedPlayers(ServerLevel world, BlockPos pos, VoidVaultServerData serverData, VoidVaultConfig config, double radius) {
        Set<UUID> set = config.playerDetector()
                .detect(world, config.entitySelector(), pos, radius, false)
                .stream()
                .filter(uuid -> !serverData.getRewardedPlayers().contains(uuid))
                .collect(Collectors.toSet());
        if (!this.connectedPlayers.equals(set)) {
            this.connectedPlayers = set;
            this.markDirty();
        }
    }

    private void markDirty() {
        this.dirty = true;
    }

    public void copyFrom(VoidVaultSharedData data) {
        this.displayItem = data.displayItem;
        this.connectedPlayers = data.connectedPlayers;
        this.connectedParticlesRange = data.connectedParticlesRange;
    }
}

package com.Polarice3.Goety.common.blocks.entities.void_vault;

import com.Polarice3.Goety.common.blocks.entities.VoidVaultBlockEntity;
import com.Polarice3.Goety.common.blocks.entities.void_spawner.VoidSpawner;
import com.Polarice3.Goety.init.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.dispenser.DefaultDispenseItemBehavior;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;

public enum VoidVaultState implements StringRepresentable {
    INACTIVE("inactive", VoidVaultState.Light.HALF_LIT) {
        @Override
        protected void onChangedTo(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            sharedData.setDisplayItem(ItemStack.EMPTY);
            VoidVaultBlockEntity.Client.spawnDeactivateParticles(world, pos);
            world.playSound(null, pos, ModSounds.VOID_VAULT_DEACTIVATE.get(), SoundSource.BLOCKS, 1.0F, (world.getRandom().nextFloat() - world.getRandom().nextFloat()) * 0.2F + 1.0F);
        }
    },
    ACTIVE("active", VoidVaultState.Light.LIT) {
        @Override
        protected void onChangedTo(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            if (!sharedData.hasDisplayItem()) {
                VoidVaultBlockEntity.Server.updateDisplayItem(world, this, config, sharedData, pos);
            }

            if (world.getBlockEntity(pos) instanceof VoidVaultBlockEntity vaultBlockEntity) {
                VoidVaultBlockEntity.Client.spawnActivateParticles(
                        world,
                        vaultBlockEntity.getBlockPos(),
                        vaultBlockEntity.getBlockState(),
                        vaultBlockEntity.getSharedData()
                );
                world.playSound(null, pos, ModSounds.VOID_VAULT_ACTIVATE.get(), SoundSource.BLOCKS, 1.0F, (world.getRandom().nextFloat() - world.getRandom().nextFloat()) * 0.2F + 1.0F);
            }

        }
    },
    UNLOCKING("unlocking", VoidVaultState.Light.LIT) {
        @Override
        protected void onChangedTo(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            world.playSound(null, pos, ModSounds.VOID_VAULT_INSERT.get(), SoundSource.BLOCKS);
        }
    },
    EJECTING("ejecting", VoidVaultState.Light.LIT) {
        @Override
        protected void onChangedTo(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            world.playSound(null, pos, ModSounds.VOID_VAULT_OPEN_SHUTTER.get(), SoundSource.BLOCKS);
        }

        @Override
        protected void onChangedFrom(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            world.playSound(null, pos, ModSounds.VOID_VAULT_CLOSE_SHUTTER.get(), SoundSource.BLOCKS);
        }
    };
    private final String id;
    private final VoidVaultState.Light light;

    VoidVaultState(String id, VoidVaultState.Light light) {
        this.id = id;
        this.light = light;
    }

    @Override
    public String getSerializedName() {
        return this.id;
    }

    public int getLuminance() {
        return this.light.luminance;
    }

    public VoidVaultState update(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
        return switch (this) {
            case INACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.activationRange());
            case ACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
            case UNLOCKING -> {
                serverData.setStateUpdatingResumeTime(world.getGameTime() + 20L);
                yield EJECTING;
            }
            case EJECTING -> {
                if (serverData.getItemsToEject().isEmpty()) {
                    serverData.finishEjecting();
                    yield updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
                } else {
                    float f = serverData.getEjectSoundPitchModifier();
                    this.ejectItem(world, pos, serverData.getItemToEject(), f);
                    sharedData.setDisplayItem(serverData.getItemToDisplay());
                    boolean bl = serverData.getItemsToEject().isEmpty();
                    int i = bl ? 20 : 20;
                    serverData.setStateUpdatingResumeTime(world.getGameTime() + i);
                    yield EJECTING;
                }
            }
        };
    }

    private static VoidVaultState updateActiveState(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData, double radius) {
        sharedData.updateConnectedPlayers(world, pos, serverData, config, radius);
        serverData.setStateUpdatingResumeTime(world.getGameTime() + 20L);
        return sharedData.hasConnectedPlayers() ? ACTIVE : INACTIVE;
    }

    public void onStateChange(ServerLevel world, BlockPos pos, VoidVaultState newState, VoidVaultConfig config, VoidVaultSharedData sharedData) {
        this.onChangedFrom(world, pos, config, sharedData);
        newState.onChangedTo(world, pos, config, sharedData);
    }

    protected void onChangedTo(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
    }

    protected void onChangedFrom(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultSharedData sharedData) {
    }

    private void ejectItem(ServerLevel world, BlockPos pos, ItemStack stack, float pitchModifier) {
        DefaultDispenseItemBehavior.spawnItem(world, stack, 2, Direction.UP, Vec3.atBottomCenterOf(pos).relative(Direction.UP, 1.2));
        VoidSpawner.addEjectItemParticles(world, pos, world.getRandom());
        world.playSound(null, pos, ModSounds.VOID_VAULT_EJECT_ITEM.get(), SoundSource.BLOCKS, 1.0F, 0.8F + 0.4F * pitchModifier);
    }

    static enum Light {
        HALF_LIT(6),
        LIT(12);

        final int luminance;

        private Light(int luminance) {
            this.luminance = luminance;
        }
    }
}

